  "Confirmed. Now create the new passkey; your browser will ask where to keep it.": "Terkonfirmasi. Sekarang buat kunci sandi baru, browsermu akan meminta lokasi penyimpanannya.",
  "Copy link": "Salin tautan",
  "Create a passkey on this device for the profile “{0}”. It signs you in here from now on.": "Buat kunci sandi pada perangkat ini untuk profil “{0}”. Ini akan memasukkanmu ke sini mulai sekarang.",
  "Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.": "Masing-masing masuk ke profil ini dari perangkat atau pengelola kata sandi yang menyimpannya. Ketuk salah satu untuk mengganti nama atau menghapusnya.",
  "Enter the code from your other device.": "Masukkan kode dari perangkatmu yang lain.",
  "For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.": "Untuk perangkat ini, kunci keamanan, pengelola kata sandi, atau ponselmu melalui kode QR browser itu sendiri. Konfirmasikan terlebih dahulu bahwa itu memang kamu.",
  "It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.": "Kunci sandi ini tidak dapat lagi digunakan untuk masuk ke profil ini. Perangkat yang sudah masuk akan tetap terhubung. Jika perangkat hilang, gunakan Keluar dari semua perangkat.",
  "It is your only way in, so it cannot be removed until there is another.": "Ini adalah satu-satunya jalan masuk kamu, sehingga tidak dapat dihapus sampai ada jalan lain.",
  "Last used {0}": "Terakhir digunakan {0}",
  "Make a new code": "Buatlah kode baru",
  "Name, e.g. Work laptop": "Nama, mis. Laptop kerja",
