  "Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.": "Menghapus rencana, sesi latihan, berat badan, foto, dan videomu dari profilmu di server ini dan di setiap perangkat yang masuk. Tindakan ini tidak dapat dibatalkan.",
