  "the configured AI provider": "penyedia AI yang dikonfigurasi",
  "Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.": "Namamu, detail masuk kamu, dan semua hal lain tentang akunmu tetap di sini. Data orang lain tidak pernah disertakan.",
  "The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Pelatih bukanlah seorang dokter atau fisioterapis. Jika ada yang sakit, tanyakan pada profesional.",
  "Not now": "Tidak sekarang",
