  "You are only notified when the Coach actually has something to suggest.": "Kamu hanya diberitahu ketika Pelatih benar-benar mempunyai sesuatu untuk disarankan.",
  "On this phone the Coach can only look while the app is open: right after a workout, or the next time you open it.": "Di ponsel ini, Pelatih hanya dapat melihat saat aplikasi terbuka: tepat setelah selesai latihan, atau saat kamu membukanya lagi.",
