  "Where are you starting from?": "Dari mana kamu memulai?",
  "How many days a week?": "Berapa hari dalam seminggu?",
  "Which days suit you? (optional)": "Hari apa yang cocok untukmu? (opsional)",
  "How long is a session?": "Berapa lama satu sesi?",
  "min": "menit",
  "The Coach fits the volume to the time you actually have, including rest between sets.": "Pelatih menyesuaikan volume dengan waktu yang sebenarnya kamu miliki, termasuk istirahat antar set.",
  "What can you train with?": "Dengan apa kamu bisa berlatih?",
  "Pick everything you have access to. Leave it empty and the Coach will use the whole library.": "Pilih semua alat yang kamu miliki. Biarkan kosong jika ingin Pelatih AI menggunakan seluruh katalog latihan.",
  "Anything to work around?": "Ada yang perlu diatasi?",
  "Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.": "Cedera, sendi yang sering bermasalah, gerakan yang tidak bisa dilakukan, atau batasan praktis seperti latihan jam 6 pagi di apartemen.",
  "e.g. “dodgy left shoulder, no barbell overhead press”": "mis. “bahu kiri sering bermasalah, hindari barbell overhead press”",
  "If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.": "Jika ada yang benar-benar sakit, temui profesional. Pelatih akan membuat program secara konservatif, namun tidak dapat mendiagnosis apa pun.",
  "Anything else?": "Ada lagi?",
  "Exercises you love": "Latihan yang kamu sukai",
  "e.g. “deadlifts, anything with a kettlebell”": "mis. “deadlift, apa pun yang menggunakan kettlebell”",
  "Exercises you would rather not": "Latihan yang tidak kamu sukai",
  "e.g. “I hate lunges”": "mis. “Aku benci lunge”",
  "Anything you want the Coach to know": "Apa pun yang kamu ingin Pelatih ketahui",
  "e.g. “I want visible arms progress by spring”": "mis. “ingin progres otot lengan terlihat jelas dalam beberapa bulan”",
  "Build my plan": "Bangun rencanaku",
