  "Revision {0}": "Revisi {0}",
  "Replaces your current week. Days this plan leaves empty become rest days.": "Menggantikan minggumu saat ini. Hari-hari yang dikosongkan oleh rencana ini menjadi hari istirahat.",
  "Could not apply those changes": "Tidak dapat menerapkan perubahan tersebut",
