  "How do you want to use openGym?": "Bagaimana kamu ingin menggunakan openGym?",
  "Use on this device": "Gunakan di perangkat ini",
  "Local keeps everything on this phone. Connecting syncs to your own openGym server instead. You can switch later in Settings.": "Lokal menyimpan semua yang ada di ponsel ini. Menghubungkan sinkronisasi ke server openGym-mu sendiri. Kamu dapat beralih nanti di Pengaturan.",
  "{0} (done)": "{0} (selesai)",
  "Workout done": "Latihan selesai",
  "reps": "repetisi",
  "Most reps in a set per workout": "Repetisi terbanyak dalam satu set per latihan",
  "Warm-up sets": "Set pemanasan",
  "Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, never below the bar on a barbell lift, and you can still change any of them mid-session.": "Ditambahkan sebelum set utama tanpa dihitung ke dalam total volume, rekor, atau progresi. Tiap set pemanasan membagi selisih menuju beban kerja utama dan tetap fleksibel diubah di tengah sesi.",
  "Ramp-up sets added before the work sets, so you do not have to add them by hand each session.": "Set ramp-up ditambahkan sebelum set utama, sehingga kamu tidak perlu menambahkannya secara manual setiap sesi.",
  "Note": "Catatan",
  "This session": "Sesi ini",
  "How it went, what to change. Saved with today’s workout.": "Bagaimana sesinya berjalan, apa yang perlu diubah. Disimpan bersama latihan hari ini.",
  "Show this next time": "Tunjukkan ini pada latihan berikutnya",
  "Brings it up again the next time you train this exercise.": "Munculkan lagi saat berikutnya kamu melatih latihan ini.",
  "Always for this exercise": "Selalu untuk latihan ini",
  "Seat height, pin position, a form cue. Shown every session.": "Tinggi dudukan, posisi pin, tips postur. Ditampilkan di setiap sesi.",
  "From {0}:": "Dari {0}:",
  "Session note": "Catatan sesi",
