  "Edit session note": "Edit catatan sesi",
  "How the session went as a whole.": "Bagaimana sesi ini berjalan secara keseluruhan.",
  "Rest-pause always trains as one warm-up set at this rep count, then one rest-pause work set. \"Sets\" isn’t used here.": "Rest-pause selalu dilatih sebagai satu set pemanasan pada jumlah repetisi ini, lalu satu set utama rest-pause. \"Set\" tidak digunakan di sini.",
  "(saved)": "(disimpan)",
  "AI Coach": "Pelatih AI",
  "API key": "Kunci API",
  "Bring my own API key": "Bawa API key saya sendiri",
  "Could not reach the provider: {0}": "Tidak dapat menghubungi penyedia: {0}",
  "Android blocks unencrypted http:// connections from apps, so this phone can only reach an https:// endpoint. Put HTTPS in front of it (Tailscale or a reverse proxy), or choose “Use my self-hosted openGym”: your server can reach an http:// model on its own network.": "Android memblokir koneksi http:// yang tidak terenkripsi dari aplikasi, sehingga ponsel ini hanya dapat menjangkau endpoint https://. Letakkan HTTPS di depannya (Tailscale atau reverse proxy), atau pilih “Gunakan openGym saya yang dihosting sendiri”: servermu dapat menjangkau model http:// di jaringannya sendiri.",
  "Each request goes straight to {0} with your key. Nobody else sees it, and you pay for it.": "Setiap permintaan dikirim langsung ke {0} dengan API key kamu. Tidak ada orang lain yang melihatnya, dan biayanya ditanggung olehmu.",
  "Endpoint": "Titik akhir",
  "Enter your API key": "Masukkan API key kamu",
  "Enter the endpoint URL": "Masukkan URL endpoint",
  "There’s no routine to review yet. Build one with at least two exercises first.": "Belum ada rutinitas untuk ditinjau. Bangun satu dengan setidaknya dua latihan terlebih dahulu.",
  "How should the Coach run?": "Bagaimana Pelatih AI harus dijalankan?",
  "List models": "Daftar model",
  "Model": "Model",
  "Nothing to change right now: {0}": "Tidak ada yang berubah saat ini: {0}",
  "Off. Choose how the Coach should run.": "Mati. Pilih cara kerja Pelatih AI.",
  "Pick a model": "Pilih model",
  "Provider": "Penyedia",
  "Runs on this phone with your own API key": "Berjalan di ponsel ini dengan API key kamu sendiri",
  "Runs on your openGym server": "Berjalan di server openGym-mu",
  "Save and use the Coach": "Simpan dan gunakan Pelatih",
  "The Coach is already thinking about your training.": "Pelatih sudah memikirkan tentang pelatihanmu.",
  "The Coach is taking a breather. You’ve used today’s {0} runs on this phone.": "Pelatih AI sedang beristirahat. Kuota {0} sesi hari ini di ponsel ini sudah habis.",
  "The Coach isn’t set up on this phone.": "Pelatih belum diatur di ponsel ini.",
  "The Coach needs your go-ahead first.": "Pelatih membutuhkan persetujuanmu terlebih dahulu.",
  "The key is stored in this phone’s secure storage and never leaves it except to call the provider.": "API key disimpan di penyimpanan aman ponsel ini dan hanya digunakan untuk menghubungi penyedia layanan.",
  "This phone calls the provider directly with your key. Every request is charged to your account.": "Ponsel ini menghubungi penyedia secara langsung dengan API key kamu. Setiap permintaan dibebankan ke akunmu.",
  "Turn the Coach off on this phone": "Nonaktifkan Pelatih di ponsel ini",
  "Use my self-hosted openGym": "Gunakan openGym saya yang dihosting sendiri",
  "What leaves this phone": "Apa yang dikirim dari ponsel ini",
  "Your server has no Coach enabled. Ask its admin, or bring your own key below.": "Servermu belum mengaktifkan Pelatih. Tanyakan pada adminnya, atau gunakan API key kamu sendiri di bawah.",
  "Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.": "Servermu menjalankan Coach dengan penyedia apa pun yang diatur oleh adminnya. Tidak ada hal baru yang meninggalkan ponsel ini selain yang sudah disinkronkan.",
  "Loading the exercise catalogue…": "Memuat katalog latihan…",
  "Checking the endpoint…": "Memeriksa endpoint…",
  "A local model can take longer.": "Model lokal bisa memakan waktu lebih lama.",
  "All optional. The more the Coach knows, the less it guesses.": "Semua opsional. Semakin banyak yang diketahui Pelatih, semakin sedikit dugaannya.",
  "Almost there": "Hampir sampai",
  "Avoid: {0}": "Hindari: {0}",
  "Before we start": "Sebelum kita mulai",
  "Building your plan…": "Membangun rencanamu…",
  "Discarded. Tell me what was off and I will build a different one.": "Dibuang. Beri tahu saya apa yang salah dan saya akan membuat yang lain.",
  "Done! Your plan is back to how it was before my last changes.": "Selesai! Rencanamu kembali seperti sebelum perubahan terakhir dari Coach.",
  "Edit my answers": "Edit jawaban saya",
  "Start a new plan": "Mulai rencana baru",
  "A fresh plan from your answers; your workouts stay": "Rencana baru berdasarkan jawabanmu; riwayat latihan tetap aman",
  "Build me a fresh plan from my answers.": "Buatkan rencana latihan baru berdasarkan jawaban saya.",
  "Experience": "Pengalaman",
  "Goal, days, equipment, limits": "Target, hari, alat, batasan",
  "Have a look at my training and tell me what you would change.": "Lihat riwayat latihanku dan beri tahu apa yang perlu disesuaikan.",
  "Here is what I am working with:": "Inilah yang saya kerjakan:",
  "Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.": "Hai, saya Pelatih kamu. Saya membuat rencanamu dari jawabanmu dan menyesuaikannya dari apa yang sebenarnya kamu catat. Tidak ada yang berubah sampai kamu mengatakannya.",
  "I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.": "Saya telah memeriksa semuanya dan tidak ada yang ingin saya ubah saat ini. Pertahankan, dan tanyakan lagi kepada saya setelah beberapa sesi lagi.",
  "I understand, let’s go": "Saya paham, ayo mulai",
  "Imported! {0} routines are in your plan and your week is set. See you at the next session.": "Berhasil diimpor! {0} rutinitas telah masuk ke jadwal mingguanmu. Selamat berlatih di sesi berikutnya!",
  "Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.": "Berhasil diimpor! {0} rutinitas telah masuk ke rencanamu. Jadwal mingguanmu tidak berubah; jadwalkan kapan pun kamu mau.",
  "It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.": "Ini merancang rencanamu dari beberapa jawaban dan menyesuaikannya dari apa yang sebenarnya kamu catat. Itu tidak akan mengubah apa pun tanpa persetujuanmu, dan kamu dapat membatalkan setiap perubahan.",
  "Routines, exercises, sets and reps, your weekly schedule and progression settings.": "Rutinitas, latihan, set dan repetisi, jadwal mingguan, serta pengaturan progresimu.",
  "Your logged training": "Catatan latihanmu",
  "Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.": "Set yang kamu catat selama periode ulasan: beban, repetisi, waktu, penilaian usaha, durasi sesi, dan catatan sesimu.",
  "Weigh-ins from the same window, and your goal weight if you set one.": "Catatan berat badan dari periode yang sama, serta target berat badanmu jika sudah diatur.",
  "What you tell the Coach": "Apa yang kamu katakan kepada Pelatih",
  "Your intake answers, including any limitations or injuries you describe.": "Jawaban masukan kamu, termasuk batasan atau cedera apa pun yang kamu gambarkan.",
  "A few preferences": "Beberapa preferensi",
  "Your unit, your language and which effort scale you log.": "Unit kamu, bahasa kamu, dan skala upaya apa yang kamu catat.",
  "Likes: {0}": "Suka: {0}",
  "Limits": "Batasan",
  "Limits: {0}": "Batas: {0}",
  "Not quite right? Say what to change below and I will revise the whole plan.": "Kurang tepat? Katakan apa yang harus diubah di bawah dan saya akan merevisi keseluruhan rencana.",
  "Pick one to continue.": "Pilih satu untuk melanjutkan.",
  "Pick what you will actually keep, not the best week you can imagine.": "Pilihlah minggu yang sebenarnya akan kamu pertahankan, bukan minggu terbaik yang dapat kamu bayangkan.",
