  "Add this device's workouts to your profile?": "Tambahkan sesi latihan perangkat ini ke profilmu?",
  "{0} workouts and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "{0} sesi latihan dan {1} catatan berat badan dicatat di perangkat ini saat belum masuk. Tambahkan ke profilmu, atau biarkan profil tetap seperti yang ada di server.",
  "{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "{0} sesi latihan dan {1} catatan berat badan dicatat di perangkat ini saat belum masuk. Tambahkan ke profilmu, atau biarkan profil tetap seperti yang ada di server.",
  "{0} workout and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "{0} sesi latihan dan {1} catatan berat badan dicatat di perangkat ini saat belum masuk. Tambahkan ke profilmu, atau biarkan profil tetap seperti yang ada di server.",
  "{0} workouts and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "{0} sesi latihan dan {1} catatan berat badan dicatat di perangkat ini saat belum masuk. Tambahkan ke profilmu, atau biarkan profil tetap seperti yang ada di server.",
