  "Offline. The server can’t be reached": "Luring. Server tidak dapat dijangkau",
  "Not an openGym answer (HTTP {0})": "Bukan jawaban openGym (HTTP {0})",
  "Your server’s address answered with something other than openGym (HTTP {0}). Your changes are kept here.": "Alamat servermu dijawab dengan sesuatu selain openGym (HTTP {0}). Perubahan kamu disimpan di sini.",
  "Server error (HTTP {0})": "Kesalahan server (HTTP {0})",
  "Your server answered with an error (HTTP {0}). Your changes are kept here.": "Servermu menjawab dengan kesalahan (HTTP {0}). Perubahan kamu disimpan di sini.",
  "The server refuses this browser": "Server menolak browser ini",
  "Your server no longer accepts this browser. Your changes are kept here.": "Servermu tidak lagi menerima browser ini. Perubahan kamu disimpan di sini.",
  "This phone is no longer paired with your server. Your changes are kept here.": "Ponsel ini tidak lagi dipasangkan dengan servermu. Perubahan kamu disimpan di sini.",
  "The server refuses this phone": "Server menolak ponsel ini",
  "Your server no longer accepts this phone. Your changes are kept here.": "Servermu tidak lagi menerima ponsel ini. Perubahan kamu disimpan di sini.",
