  "Couldn’t keep a copy of the changes on this device. Nothing was removed.": "Tidak dapat menyimpan salinan perubahan di perangkat ini. Tidak ada yang dihapus.",
  "Not everything is on your server yet": "Belum semuanya ada di servermu",
  "Not on your server yet: {0}": "Belum ada di servermu: {0}",
  "Some changes on this device have not reached your server.": "Beberapa perubahan pada perangkat ini belum sampai ke servermu.",
  "Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Coba lagi, atau ekspor cadangan terlebih dahulu. Tetap lanjutkan untuk menyimpan salinan perubahan ini di perangkat hingga terhubung kembali ke server dengan akun ini. Lalu perubahan tersebut akan disinkronkan kembali.",
  "Syncing…": "Menyinkronkan…",
  "Try again": "Coba lagi",
  "Last synced: {0}": "Terakhir disinkronkan: {0}",
  "Not synced with this server yet": "Belum disinkronkan dengan server ini",
  "Server & sync": "Server & sinkronisasi",
  "Signed in as {0}": "Masuk sebagai {0}",
  "Sync now": "Sinkronkan sekarang",
  "Your changes are kept here, and merged into your account once it is paired again.": "Perubahan kamu disimpan di sini, dan digabungkan ke dalam akunmu setelah dipasangkan kembali.",
  "Your changes are kept here, and merged into your account once you are signed in again.": "Perubahan kamu disimpan di sini, dan digabungkan ke dalam akunmu setelah kamu masuk kembali.",
  "Changes kept for {0}": "Perubahan disimpan untuk {0}",
  "Added back when this device connects as that account again.": "Ditambahkan kembali saat perangkat ini terhubung kembali sebagai akun itu.",
  "The changes your server has not seen are kept on this device, and added back when it connects as this account again.": "Perubahan yang belum dilihat servermu disimpan di perangkat ini, dan ditambahkan kembali saat perangkat terhubung kembali sebagai akun ini.",
  "This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.": "Ponsel ini beralih kembali ke mode lokal dan salinan akunmu akan dihapus. Ponsel akan memeriksa terlebih dahulu apakah server memiliki semua perubahan. Jika belum, kamu bisa memilih tindakan untuk perubahan tersebut.",
  "Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.": "Datamu dihapus dari browser ini; profilmu di server tetap menyimpannya. Sistem akan memeriksa terlebih dahulu apakah server memiliki semua perubahan. Jika belum, kamu bisa memilih tindakan untuk perubahan tersebut.",
  "Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.": "Keluar dari profil ini di semua perangkat, termasuk perangkat ini. Ponsel yang terhubung akan terputus dan harus dipasangkan ulang. Kunci sandimu tetap aktif, jadi kamu bisa masuk kembali kapan saja.",
  "{0} change": "{0} perubahan",
  "{0} changes": "{0} perubahan",
  "Default progression": "Progresi default",
  "Planned sessions start from": "Sesi yang direncanakan dimulai dari",
  "The routine’s sets and reps. Your history decides the weight.": "Set dan repetisi dari rutinitas. Beban ditentukan dari riwayat latihanmu.",
  "Your last session": "Sesi terakhir kamu",
  "The reps you logged last time in that routine, carried over, and any warm-ups you set up yourself. With progression off, the weight too.": "Repetisi dari sesi terakhir di rutinitas tersebut akan disalin, termasuk pemanasan yang kamu atur sendiri. Jika progresi dimatikan, bebannya juga ikut disalin.",
  "Last time means": "Terakhir kali artinya",
  "This routine": "Rutinitas ini",
  "Your last session of the exercise in the same routine. Heavy day and light day stay apart.": "Sesi latihan terakhir kamu dalam rutinitas yang sama. Hari berat dan hari ringan tetap terpisah.",
  "Any workout": "Latihan apa pun",
  "The last time you did the exercise, whichever routine it was in.": "Terakhir kali kamu melakukan latihan, apa pun rutinitasnya.",
  "Plan changed, so starting from your new target.": "Rencana diubah, jadi mulailah dari target baru kamu.",
  "First time in this routine, so starting from its own target.": "Pertama kali dalam rutinitas ini, jadi dimulai dari target sendiri.",
  "No weight logged last time. Enter what you lift and progression takes it from there.": "Belum ada catatan beban sebelumnya. Masukkan beban angkatanmu dan progresi otomatis akan menghitung dari sana.",
