  "Pause": "Jeda",
  "Keep timing after target": "Lanjutkan timer setelah mencapai target",
  "Timed sets continue up to 15 extra minutes. Tap Done to log the actual duration.": "Set berdurasi terus berjalan hingga 15 menit tambahan. Ketuk Selesai untuk mencatat durasi sebenarnya.",
  "Edit workout": "Edit latihan",
  "Workout updated": "Latihan diperbarui",
  "Save workout changes?": "Simpan perubahan latihan?",
  "Save your edits to this workout, or keep the original record.": "Simpan hasil edit kamu pada latihan ini, atau simpan catatan aslinya.",
  "Save changes": "Simpan perubahan",
  "Don't save": "Jangan simpan",
  "Keep editing": "Lanjutkan mengedit",
  "This workout was deleted on another device. Your edits are still here.": "Latihan ini telah dihapus di perangkat lain. Hasil edit kamu masih ada di sini.",
  "Close editor": "Tutup editor",
  "Editing a saved workout. Date and duration stay unchanged.": "Mengedit latihan yang disimpan. Tanggal dan durasi tidak berubah.",
  "A pull for every press, so the shoulders stay balanced.": "Gerakan tarik untuk setiap gerakan dorong, agar bahu tetap seimbang.",
  "A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.": "Rotasi dua hari untuk tiga sesi seminggu, disesuaikan dengan alat yang kamu punya. Gerakan compound di awal, satu gerakan tarik untuk setiap gerakan dorong, serta pembagian jadwal yang pas agar tidak ada otot yang terlewat hingga dua minggu.",
  "Based on the training already in this demo profile.": "Berdasarkan pelatihan yang sudah ada di profil demo ini.",
  "Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.": "Berat badan stagnan selama empat minggu padahal targetnya naik berat badan. Ini soal asupan nutrisi, bukan soal latihan. Rencana latihanmu sudah tepat.",
  "Demo": "Demo",
  "Demo data reset": "Penyetelan ulang data demo",
  "Direct arm work, since you asked for it.": "Latihan isolasi lengan, sesuai permintaanmu.",
  "Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.": "Setiap set teratas pada latihan ini mencapai RPE 9,5 ke atas selama tiga sesi berturut-turut dan bebannya stagnan. Mengganti variasi gerakan selama empat minggu biasanya lebih efektif menembus stagnasi daripada memaksakan gerakan yang sama.",
  "Example data, stored only in this browser. Go wild and change anything you like.": "Data contoh, hanya tersimpan di browser ini. Silakan coba-coba dan ubah apa pun sesukamu.",
  "Full body A": "Seluruh tubuh A",
  "Full body B": "Seluruh tubuh B",
  "Horizontal pressing, the other half of the session.": "Gerakan dorong horizontal (horizontal press), melengkapi paruh sesi ini.",
  "Live demo. Everything stays in this browser.": "Demo langsung. Semuanya tetap ada di browser ini.",
  "No training history yet, so starting conservatively.": "Belum ada riwayat pelatihan, jadi mulailah secara konservatif.",
  "Passkey sign-in, sync across your devices, your own data.": "Masuk dengan kunci sandi, sinkronkan di seluruh perangkatmu, datamu sendiri.",
  "Puts the example plan, workouts and weigh-ins back the way they started.": "Mengembalikan contoh rencana, latihan, dan penimbangan ke awal.",
  "Reset": "Atur ulang",
  "Reset demo data": "Atur ulang data demo",
  "Reset demo data?": "Atur ulang data demo?",
  "Revised as you asked. Everything you did not question is exactly as it was.": "Direvisi sesuai permintaan kamu. Segala sesuatu yang tidak kamu pertanyakan persis seperti aslinya.",
  "Same pattern, higher reps than day A.": "Pola yang sama, repetisi lebih tinggi dari hari A.",
  "Self-host it in a minute →": "Host sendiri dalam semenit →",
  "Self-host openGym": "Host sendiri openGym",
  "Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.": "Durasi sesi belakangan ini lewat sekitar lima belas menit dari target. Ini latihan tambahan (accessory) yang paling aman dikurangi satu set.",
  "Start the demo": "Mulai demonya",
  "The main lower-body driver, where most of the strength comes from.": "Penggerak utama tubuh bagian bawah, tempat sebagian besar kekuatan berasal.",
  "The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.": "Pola yang sama, variasi yang berbeda: cukup tumpang tindih untuk maju, cukup perbedaan untuk tetap segar.",
  "The two big lower-body and pressing patterns first, while you are fresh.": "Dua gerakan utama tubuh bagian bawah dan dorong di awal sesi, selagi tenagamu masih penuh.",
  "This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.": "Demo ini sepenuhnya berjalan di browsermu pada data contoh. Tidak ada yang dikirim ke mana pun. Masuk dan sinkronisasi kunci sandi di seluruh perangkatmu dilengkapi dengan server openGym, yang kamu dapatkan dengan menghostingnya sendiri.",
  "Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.": "Ada tiga hal yang perlu disesuaikan dan satu catatan penting. Selebihnya berjalan lancar: squat dan latihan pull berjalan sesuai target.",
  "Vertical pressing.": "Gerakan dorong vertikal (vertical press).",
  "You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.": "Kamu sudah memindahkan sesi ini ke hari Sabtu selama tiga minggu berturut-turut. Lebih baik jadwal di rencana langsung disesuaikan daripada harus mengubahnya terus.",
