  "Your server was reached, but it refused the app’s request (CORS). If a reverse proxy such as Traefik adds CORS headers, let requests from {0} through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Servermu berhasil dihubungi, tetapi menolak permintaan aplikasi (CORS). Jika reverse proxy seperti Traefik menambahkan header CORS, teruskan permintaan dari {0} ke openGym tanpa diubah. Lihat “Phone app and CORS” di docs/SELF_HOSTING.md.",
  "Could not reach {0}. Check the address and that this phone can reach it.": "Tidak dapat menjangkau {0}. Periksa alamatnya dan pastikan ponsel ini dapat menghubunginya.",
  "The end of a rest or a hold buzzes like an alarm, even in silent mode.": "Saat waktu istirahat atau tahan selesai, perangkat akan bergetar/berbunyi seperti alarm meskipun dalam mode senyap.",
