  "openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGym tidak dapat lagi menulis ke “{0}”, jadi salinannya masuk ke Dokumen/openGym lagi. Pilih folder lagi untuk beralih kembali.",
  "openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGym tidak dapat lagi menulis ke folder yang dipilih, jadi salinannya masuk ke Documents/openGym lagi. Pilih folder lagi untuk beralih kembali.",
  "Nudge me when I skip a planned workout": "Ingatkan jika saya melewatkan jadwal latihan",
  "Nudge tone": "Gaya pengingat",
  "Friendly": "Ramah",
  "Guilt trip": "Sindiran halus",
  "Drill sergeant": "Instruktur militer",
  "One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.": "Satu pengingat santai di malam hari saat tidak ada latihan yang dicatat, antara pukul 20:00 dan 21:30. Setelah 3 hari berturut-turut terlewat, pengingat berhenti sementara hingga kamu mencatat latihan berikutnya.",
  "Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.": "Mencatat latihan di perangkat lain? Sebelum pengingat dikirim, ponsel mengecek ke server selama aplikasi diizinkan berjalan di latar belakang. Membuka aplikasi akan otomatis menyinkronkan data.",
  "Everything okay?": "Semuanya aman?",
  "{0} is still waiting. What’s up?": "{0} masih nungguin nih. Ada kendala apa?",
  "No {0} today? Even a short session tomorrow counts.": "Nggak sempat {0} hari ini? Sesi singkat besok pun tetap berarti.",
  "Rough day? {0} will keep. Tomorrow is a fresh start.": "Hari yang melelahkan? {0} bisa menunggu. Besok kita mulai lagi.",
  "Hey, {0} didn’t happen today. All good?": "Hei, jadwal {0} terlewat hari ini. Semuanya baik-baik saja?",
  "I miss you": "Kangen latihan bareng",
  "{0} waited by the door all evening. For you.": "{0} nungguin di dekat pintu semalaman. Demi kamu lho.",
  "The barbell asked about you today. I didn’t know what to say.": "Barbel sempat nanyain kamu hari ini. Bingung mau jawab apa.",
  "Was it something I said? {0} misses you.": "Ada yang salah ya? {0} kangen kamu nih.",
  "I saved you a spot on the bench. It’s still empty.": "Udah disiapin tempat di bangku latihan. Tapi masih kosong.",
  "Attention, recruit!": "Perhatian, prajurit!",
  "Your gains are packing their bags. {0} tomorrow, no excuses!": "Gains-mu udah mau kabur tuh. Latihan {0} besok, tanpa alasan!",
  "{0} doesn’t do itself, recruit. Move it!": "{0} nggak bakal jalan sendiri, prajurit. Ayo gerak!",
  "Excuses don’t lift weights. Report for {0} tomorrow!": "Banyak alasan nggak bikin beban terangkat! Siap latihan {0} besok!",
  "Your muscles filed a missing-person report. Show up for {0}!": "Ototmu sampai bikin laporan orang hilang. Datang dan selesaikan {0}!",
  "That address answers, but it isn’t an openGym server. Check the URL.": "Alamat itu menjawab, tapi ini bukan server openGym. Periksa URL-nya.",
  "That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Alamat tersebut merespons, tetapi yang menjawab adalah halaman login atau aturan proxy, bukan openGym. Teruskan /api/ ke openGym tanpa diubah. Lihat “Phone app and CORS” di docs/SELF_HOSTING.md.",
  "Switch sides": "Ganti sisi",
