  "Effort per set is off. Turn it on in Settings → Workout to keep rating.": "Tingkat usaha per set sedang nonaktif. Aktifkan di Pengaturan → Latihan untuk mempertahankan rating.",
  "Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.": "Masukkan kode yang ditampilkan perangkatmu yang lain di Pengaturan → Akun → Tambahkan perangkat lain. Perangkat ini kemudian mendapatkan kunci sandinya sendiri.",
  "Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.": "Buka Pengaturan → Akun → “Pasangkan aplikasi seluler” di situs openGym tempat kamu sudah terhubung, lalu masukkan alamatnya dan kode yang ditampilkan di sana.",
  "Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.": "Buka Pengaturan → Akun → “Pasangkan aplikasi seluler” di situs openGym-mu di browser dan masukkan kode baru yang ditampilkan di sana. Apa yang disimpan ponsel ini digabungkan ke dalam akunmu.",
