  "The weights you own, one bell each. Progression, deloads, warm-ups and the + and − buttons of dumbbell lifts land only on these.": "Koleksi dumbbell milikmu. Progresi beban, deload, pemanasan, serta tombol + dan − pada latihan dumbbell hanya akan menggunakan daftar ini.",
