  "To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:": "Untuk menjawabnya, perangkat ini mengirimkan ini langsung ke {0}, layanan AI di luar openGym, dengan API key kamu:",
  "Who may see your training": "Siapa yang dapat melihat data latihanmu",
  "Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.": "Kepada siapa Pelatih dapat mengirimkan data latihanmu dari perangkat ini. Tarik izin dan Pelatih akan bertanya lagi lain kali. Model di jaringan kamu sendiri tidak perlu izin.",
