  "Removes your profile and everything in it from this server.": "Menghapus profilmu dan semua isinya dari server ini.",
  "Delete your account?": "Hapus akunmu?",
  "Your profile, workouts, body weight, photos and videos are deleted from this server for good. There is no undo, and not even your admin can bring them back.": "Profil, sesi latihan, berat badan, foto, dan videomu akan dihapus selamanya dari server ini. Tindakan ini tidak dapat dibatalkan, bahkan oleh adminmu sekalipun.",
  "Want a copy first? Export a backup. You can import it into openGym anytime.": "Mau copy dulu? Ekspor cadangan. Kamu dapat mengimpornya ke openGym kapan saja.",
