  "You’re the only admin here, and other profiles still use this server. Make someone else an admin first.": "Kamu satu-satunya admin di sini, dan profil lain masih menggunakan server ini. Jadikan orang lain sebagai admin terlebih dahulu.",
  "Couldn’t delete the account. Nothing was removed.": "Tidak dapat menghapus akun. Tidak ada yang dihapus.",
  "Your account is gone. Thanks for every rep.": "Akunmu telah dihapus. Terima kasih untuk setiap repetisi perjuanganmu! 💪",
