  "On the watch": "Di jam tangan",
  "Fewer things, bigger numbers. Pick what helps you mid-set.": "Lebih sedikit hal, jumlah lebih besar. Pilih apa yang membantumu di pertengahan set.",
  "Exercise animation": "Animasi latihan",
  "Heart rate": "Detak jantung",
  "Time so far": "Waktu sejauh ini",
  "Calories": "Kalori",
  "Next exercise during the rest": "Latihan selanjutnya saat istirahat",
  "Ring": "Lingkaran",
  "Countdown only": "Hanya hitung mundur",
  "Your bars": "Barbelmu",
  "Set the bar once for every exercise of a type.": "Tetapkan standar satu kali untuk setiap jenis latihan.",
  "Your bar for this type, set in Your bars.": "Barbel pilihanmu untuk jenis ini, atur di menu Barbelmu.",
  "What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.": "Berat barbel standar di gym kamu. Setiap latihan dengan barbel tersebut menghitung plat dari sini, kecuali diatur khusus. Beban yang dicatat tetap beban total.",
  "Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.": "Sebagian besar gerakan di katalog menggunakan “{0}”, beberapa menggunakan “{1}”. Menggunakan bar pendek untuk semuanya berarti kamu perlu mengatur keduanya.",
  "Back to the standard bars": "Kembali ke bar standar",
  "Standard bars. Tap if yours are lighter.": "Barbel standar. Ketuk jika barbelmu lebih ringan.",
  "The last warm-up still gets the full rest before your first work set.": "Pemanasan terakhir tetap mendapat waktu istirahat penuh sebelum set utama pertama.",
  "Days per week": "Hari per minggu",
  "Hours": "Jam",
  "h": "h",
  "This device has 1 workout that is not in this backup. Replacing deletes it.": "Perangkat ini memiliki 1 sesi latihan yang tidak ada dalam cadangan ini. Mengganti data akan menghapusnya.",
  "This device has {0} workouts that are not in this backup. Replacing deletes them.": "Perangkat ini memiliki {0} sesi latihan yang tidak ada dalam cadangan ini. Mengganti data akan menghapusnya.",
