  "Heart rate from your watch fills in each set.": "Detak jantung dari jam tanganmu otomatis mengisi setiap set.",
  "Weigh-ins from your smart scale land here.": "Data penimbangan dari timbangan pintar muncul di sini.",
  "Finished workouts and weigh-ins go to Health Connect.": "Sesi latihan yang selesai dan penimbangan badan dikirim ke Health Connect.",
  "Bring your Hevy history over with a Pro API key.": "Pindahkan riwayat Hevy-mu menggunakan API key Pro.",
  "Workouts, routines and weigh-ins, once.": "Sesi latihan, rutinitas, dan penimbangan badan, cukup sekali.",
