  "Plain http:// only works for an address on your home network, like 192.168.x.x, a .local name or a Tailscale 100.x address. Anything on the internet needs https://.": "http:// biasa hanya berfungsi untuk alamat di jaringan rumahmu, seperti 192.168.x.x, nama .local, atau alamat Tailscale 100.x. Apa pun di internet memerlukan https://.",
  "Plain http only on your home network": "http biasa hanya di jaringan rumahmu",
  "Freestyle repeats what you did last time, with no progression rule. Rules apply to exercises in a routine.": "Gaya bebas mengulang sesi terakhirmu tanpa aturan progresi. Aturan hanya berlaku untuk latihan dalam rutinitas.",
