  "For this workout": "Untuk latihan ini",
  "Heavy lifts get more rungs, light ones one or none.": "Latihan berat mendapat lebih banyak tahapan, latihan ringan mendapat satu atau tanpa tahapan.",
  "It hurts": "Terasa sakit",
  "It hurts, it’s taken, no time, feeling great": "Terasa sakit, alat dipakai, tidak ada waktu, kondisi prima",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "Terasa ngilu, jadi kurangi beban untuk sisa set. Berhenti jika masih sakit.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "Terasa ngilu, jadi sisa set dialihkan ke gerakan yang melatih otot yang sama dari sudut yang lebih aman.",
  "Keep these warm-ups": "Simpan pemanasan ini",
  "Kept. Same warm-ups next time, scaled to your work weight.": "Tersimpan. Pemanasan yang sama untuk sesi berikutnya, disesuaikan dengan beban kerjamu.",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Set yang sudah dicatat dan rutinitasmu tidak berubah. Coach bukan dokter atau fisioterapis. Jika ada yang terasa sakit, tanyakan kepada profesional.",
  "Looking at your workout…": "Memeriksa latihanmu…",
