  'This sound cannot be read here. Try an MP3, M4A, WAV or OGG file.': 'Suara ini tidak bisa dibaca di sini. Coba file MP3, M4A, WAV, atau OGG.',
  'Up to 30 seconds, from an MP3, M4A, WAV or OGG file. Silence at either end is trimmed off.': 'Maksimal 30 detik, dari file MP3, M4A, WAV, atau OGG. Bagian hening di awal dan akhir dipotong.',
