  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "Direncanakan, tidak latihan. Tidak apa-apa: kamu latihan di hari lain, jadi minggu itu tetap terhitung.",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "Simpan 1 freeze, didapat tiap 4 minggu latihan. Dua minggu terlewat berturut-turut mengakhiri streak.",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "Simpan hingga 2 freeze, satu tiap 4 minggu latihan. Bahkan dua minggu terlewat berturut-turut bisa ditutup.",
  "Change the freeze rule": "Ubah aturan freeze",
  "Every 4th week you train earns a freeze. You can bank 1.": "Setiap minggu latihan ke-4 memberi satu freeze. Kamu bisa menyimpan 1.",
  "Every week counts. Miss one and the streak starts over.": "Setiap minggu dihitung. Lewatkan satu dan streak mulai dari awal.",
  "From now on: {0}.": "Mulai sekarang: {0}.",
