  "How strict should your streak be?": "Seberapa ketat streak kamu?",
  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "Melewatkan seminggu? Satu freeze menutupinya: streak tetap jalan, minggu itu hanya tidak menambah apa-apa. Dua minggu terlewat berturut-turut, dan streak mulai dari awal.",
  "No freezes": "Tanpa freeze",
  "No freezes on your rule. Every week counts.": "Aturanmu tidak punya freeze. Setiap minggu dihitung.",
  "No freezes on your rule: a week without a workout starts it over.": "Aturanmu tidak punya freeze: seminggu tanpa latihan dan streak mulai dari awal.",
  "No workout, and your rule has no freezes, so the streak started over.": "Tidak ada latihan, dan aturanmu tidak punya freeze, jadi streak mulai dari awal.",
  "Weeks already counted stay as they are.": "Minggu yang sudah dihitung tetap seperti adanya.",
