  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Ini publik untuk semua orang di server ini: siapa pun yang punya akun di sini bisa melihat, mencoba, dan menyalinnya. Nama dan tanggalmu selalu ikut bersamanya. Bagikan hanya yang memang milikmu: sesuatu yang kamu buat, rekam, atau berhak kamu teruskan. Gambar dan animasi latihan dari pustaka bawaan berlisensi dan tidak akan pernah bisa dibagikan. Kamu bisa berhenti berbagi kapan saja; salinan yang sudah diambil orang lain tetap ada pada mereka.",
