  "Last time and the next weight come from this gym only.": "Terakhir kali dan beban berikutnya hanya diambil dari gym ini.",
  "Brand at {0}": "Merek di {0}",
  "Life Fitness, Technogym… (optional)": "Life Fitness, Technogym… (opsional)",
  "Same brand at another gym? It shares these numbers. Records and Stats still count every gym.": "Merek yang sama di gym lain? Angkanya dipakai bersama. Rekor dan Statistik tetap menghitung semua gym.",
  "For machines and cables that feel different from gym to gym. Free weights rarely need it.": "Untuk mesin dan kabel yang terasa beda di tiap gym. Beban bebas jarang perlu ini.",
  "All gyms": "Semua gym",
  "Today’s planned rows for {0} didn’t fit, so the routine’s own are up: {1}": "Set yang direncanakan untuk {0} tidak cocok, jadi yang dipakai set dari rutinnya: {1}",
  "Today’s rows come from {0}. Your routine stays as it is.": "Set hari ini dari {0}. Rutinmu tetap seperti semula.",
  "Today’s rows were planned for this day. Your routine stays as it is.": "Set hari ini direncanakan untuk hari ini. Rutinmu tetap seperti semula.",
  "Body composition from your scale": "Komposisi tubuh dari timbanganmu",
  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Lemak tubuh dan massa tanpa lemak, seperti yang disimpan timbanganmu. Tampil di Ukuran tubuh, tidak pernah tercampur dengan yang kamu catat.",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Lemak tubuh, massa tanpa lemak, massa tulang, air tubuh, dan BMR, seperti yang disimpan timbanganmu. Tampil di Ukuran tubuh, tidak pernah tercampur dengan yang kamu catat.",
  "From Health Connect": "Dari Health Connect",
