  "New token": "Token baru",
  "No tokens yet. Make one for each program, so you can revoke them one by one.": "Belum ada token. Buat satu untuk tiap program, supaya bisa dicabut satu per satu.",
  "Pick at least one thing it may see.": "Pilih setidaknya satu hal yang boleh dilihat.",
  "Revoke": "Cabut",
